-- Rollback de 202611200009_sync_base_from_active_patch.sql
-- Saca los triggers y vuelve las tablas base a los valores que tenían antes de la
-- sincronización inicial (lo que la migración cambió, columna por columna).

drop trigger if exists rune_patch_sync_base on public.rune_patch_data;
drop trigger if exists item_patch_sync_base on public.item_patch_data;
drop trigger if exists champion_patch_sync_base on public.champion_patch_stats;
drop trigger if exists game_state_sync_base on public.game_state;
drop function if exists public.sync_catalog_base_on_active_patch();
drop function if exists public.sync_catalog_base_from_patch();
drop function if exists public.sync_catalog_base_from_patch_id(bigint);
drop function if exists public.sync_catalog_base_row(regclass, text, jsonb);
drop function if exists public.catalog_sync_excluded_columns();

update public.runes b set ("description") = (select r."description" from jsonb_populate_record(b, $rd${"description":"Dentro de 3 seg, impacta al mismo campeón enemigo con 3 ataques o habilidades básicas para infligir daño adaptable adicional al objetivo. \n Valor de daño: 40-210 + 10% adicional de Daño de Ataque + 5% Poder de Habilidad. \n Enfriamiento: de 20 a 13 seg."}$rd$::jsonb) r) where b.id::text = '6a04bc5f681bf773dac12a86';
update public.runes b set ("description") = (select r."description" from jsonb_populate_record(b, $rd${"description":"Tus ataques y habilidades envían a Aery a un objetivo, lo que inflige daño a enemigos o escuda a aliados.\n Daño: 15 a 70 + 10% de daño de ataque adicional + 5% de poder de habilidad\n Escudo: 25 a 120 + 10% de daño de ataque adicional + 5% de poder de habilidad\n No puedes volver a lanzar a Aery hasta que regrese a ti."}$rd$::jsonb) r) where b.id::text = '6a04bc5f681bf773dac12a99';
update public.runes b set ("description") = (select r."description" from jsonb_populate_record(b, $rd${"description":"Cada 3 seg en combate, tu siguiente ataque contra un campeón se potenciará.\n Daño mágico adicional: 3.3% de tu Vida \n Curación: 1.3% de tu Vida\n Aumento de Vida de forma permanente: 10\n En campeones a distancia, los efectos se reducen en un 60%"}$rd$::jsonb) r) where b.id::text = '6a04bc5f681bf773dac12a9f';
update public.runes b set ("description") = (select r."description" from jsonb_populate_record(b, $rd${"description":"Al atacar a campeones enemigos, obtienes velocidad de ataque acumulable. Se acumula hasta 6 veces. Al alcanzar el máximo de acumulaciones, obtienes alcance adicional y puedes superar tu limite de velocidad de ataque.\n Cada acumulacion aumenta la Velocidad de Ataque de un 6 a un 14% (cuerpo a cuerpo) o de un 3.5 a un 8% (a distancia) durante 6 seg.\n Al alcanzar el máximo de acumulaciones, obtienes 25 (cuerpo a cuerpo) o 50 (a distancia) de alcance."}$rd$::jsonb) r) where b.id::text = '6a04bc5f681bf773dac12aae';
update public.runes b set ("description") = (select r."description" from jsonb_populate_record(b, $rd${"description":"Obtienes acumulaciones de fuerza adaptable al atacar a un campeón con habilidades o ataques separados. Se acumula hasta 6 veces. Al máximo de acumulaciones, obtienes omnivampirismo adicional.\n Por acumulación: 3 a 5 de Daño de Ataque adicional o 4 a 8 de Poder de Habilidad adicional durante 6 seg.\n Bonus al máximo de acumulaciones: Cuerpo a cuerpo: 9% | A distancia 5% de Omnivampirismo adicional."}$rd$::jsonb) r) where b.id::text = '6a04bc5f681bf773dac12aaf';
update public.runes b set ("description") = (select r."description" from jsonb_populate_record(b, $rd${"description":"Inflige de 10 a 45 de daño verdadero adicional a los enemigos cuyo movimiento esté limitado (7 seg de enfriamiento)."}$rd$::jsonb) r) where b.id::text = '6a04bc5f681bf773dac12ab2';
update public.runes b set ("description") = (select r."description" from jsonb_populate_record(b, $rd${"description":"Al impactar a un campeón enemigo con un ataque o una habilidad, tú y el campeón aliado cercano con la menor cantidad de vida se curan. \n\n Aliado: Recupera un 1.5% de Vida Máxima + un 5% de Poder de Habilidad. \n\n Tú: Recuperas un 1% de tu Vida Máxima + un 5% de tu Poder de Habilidad. Enfriamiento: 20 seg. \n\n Si eres un campeón cuerpo a cuerpo, la curación tiene un 130% de efectividad. (No se activa si tú o tus aliados cercanos tienen la vida al máximo; tampoco se activa si no hay aliados cerca)."}$rd$::jsonb) r) where b.id::text = '6a04bc5f681bf773dac12a83';
update public.wr_items b set ("mana", "price", "description", "ability_haste", "attack_damage") = (select r."mana", r."price", r."description", r."ability_haste", r."attack_damage" from jsonb_populate_record(b, $rd${"mana":300,"price":2700,"description":"Asombro: Otorga Daño de Ataque igual al 1.5% de Maná Máximo y restaura el 15% de todo el maná gastado. \n Carga de Maná: Aumenta el Maná Máximo en 18 cada vez que gastas maná o en cada ataque. Tiene un límite de 700 de Maná adicional y transforma a Manamune en Muramaná. Se activa hasta 3 veces cada 10 seg. Solo puedes llevar un objeto de Lágrima de la Diosa a la vez.","ability_haste":20,"attack_damage":25}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e030';
update public.wr_items b set ("description", "attack_damage") = (select r."description", r."attack_damage" from jsonb_populate_record(b, $rd${"description":"Infinidad: Los golpes críticos infligen un 205% de daño en vez de 175%. \n Romper el Límite: Cuando la cantidad total de Tasa de Críticos que haz obtenido de los objetos supera un 100%, cada 1% de Tasa de Críticos que excede el límite otorga un 0.6% de daño crítico adicional.","attack_damage":65}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e036';
update public.wr_items b set ("price", "description", "attack_speed", "attack_damage") = (select r."price", r."description", r."attack_speed", r."attack_damage" from jsonb_populate_record(b, $rd${"price":900,"description":"Descarga: Los ataques energizados infligen 50 de daño mágico adicional. Al desplazarte y atacar generas ataques energizados","attack_speed":0,"attack_damage":15}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e032';
update public.wr_items b set ("price", "attack_speed") = (select r."price", r."attack_speed" from jsonb_populate_record(b, $rd${"price":1400,"attack_speed":30}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e033';
update public.wr_items b set ("price", "description", "percentage_movement") = (select r."price", r."description", r."percentage_movement" from jsonb_populate_record(b, $rd${"price":3000,"description":"Cortar: +15 de Penetración de Armadura. \n Impulso: Moverte genera Impulso, lo que te otorga hasta 40 de Velocidad de Movimiento al tener 100 acumulaciones. Atacar elimina todas las acumulaciones de Impulso. Las acumulaciones decaen cuando se afecta la velocidad de movimiento. Aceleración Espectral: Atacar con el max de Impulso otorga un 25% de Velocidad de Ataque durante 4 seg.\n ","percentage_movement":0}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e034';
update public.wr_items b set ("price", "description", "ability_haste", "attack_damage") = (select r."price", r."description", r."ability_haste", r."attack_damage" from jsonb_populate_record(b, $rd${"price":2700,"description":"Asombro: Otorga Daño de Ataque igual al 1.5% de Maná Máximo y restaura el 15% de todo el maná gastado.\n Impacto: Cuando un ataque impacta contra un campeón enemigo, drena un 2.5% del maná actual y le inflige daño físico adicional igual a la cantidad consumida. Al infligir daño de habilidad a campeones enemigos, drena un 4% del maná actual e inflige daño físico adicional igual a la cantidad consumida + un 6% de daño de ataque. Este efecto solo se activa cuando el maná restante es mayor al 20%. Un solo ataque o habilidad unicamente activará este efecto una vez contra el mismo campeón.","ability_haste":20,"attack_damage":25}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e037';
update public.wr_items b set ("price") = (select r."price" from jsonb_populate_record(b, $rd${"price":3400}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e038';
update public.wr_items b set ("tenacity", "description") = (select r."tenacity", r."description" from jsonb_populate_record(b, $rd${"tenacity":0,"description":"Severo: +50% del daño de ataque básico como daño físico adicional.\n Salvavidas: Al recibir daño que te haga bajar del 35% de vida, recibes un escudo equivalente al 75% de la adicional que se desvanece a lo largo de 5 s. (75 s de enfriamiento).\n Furia de Sterak: Activar Salvavidas aumenta tu tamaño y te otorga un 30% de tenacidad durante 8 s."}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e03a';
update public.wr_items b set ("price", "description", "attack_speed", "percentage_movement") = (select r."price", r."description", r."attack_speed", r."percentage_movement" from jsonb_populate_record(b, $rd${"price":2900,"description":"Furia del Viento: Los ataques impactan a 2 enemigos cercanos adicionales, cada uno inflige un 55% de daño de ataque. Esos ataques pueden infligir golpes criticos y activar efectos al impacto. \n Espada del Viento: Los ataques infligen 15 de daño físico adicional al impacto contra campeones.","attack_speed":35,"percentage_movement":0}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e03f';
update public.wr_items b set ("armor", "price", "description", "attack_damage") = (select r."armor", r."price", r."description", r."attack_damage" from jsonb_populate_record(b, $rd${"armor":40,"price":3100,"description":"Desafiar: Los derribos de campeones disipan la acumulación de daño restante de Cauterizar y restauran un 8% de tu Vida Máxima a lo largo de 2 seg. \n Cauterizar: Recibes un 27% de todo el daño físico y el daño mágico que te inflinjan (12% para campeones a distancia) a lo largo de 3 seg como daño verdadero.","attack_damage":35}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e041';
update public.wr_items b set ("price", "description", "attack_speed") = (select r."price", r."description", r."attack_speed" from jsonb_populate_record(b, $rd${"price":3200,"description":"Sed: +10% de Omnivampirismo. \n Ataques Arruinados: Los ataques infligen daño físico adicional al impacto igual al 7% de la Vida actual del enemigo. (Los ataques cuerpo a cuerpo infligen 10%). Daño mínimo: 15. Max. daño contra monstruos: 60. \n Drenar: Alcanzar a un campeón con 3 ataques o habilidades inflige de 30 a 100 de daño mágico y roba un 25% de su Velocidad de Movimiento durante 2 seg. (60 seg de enfriamiento).","attack_speed":35}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e043';
update public.wr_items b set ("price", "attack_speed", "attack_damage") = (select r."price", r."attack_speed", r."attack_damage" from jsonb_populate_record(b, $rd${"price":3300,"attack_speed":15,"attack_damage":25}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e044';
update public.wr_items b set ("description", "attack_damage") = (select r."description", r."attack_damage" from jsonb_populate_record(b, $rd${"description":"Espada Encantada: Lanzar una habilidad genera una carga de Espada Encantada (máx. de 2 cargas) que dura hasta 10 seg. Impactar a un enemigo con un ataque consume una carga para infligir un 70% del ataque básico como daño físico y otorga 40 de Velocidad de Movimiento durante 2 seg. Este daño adicional puede asestar golpes críticos. Cada habilidad solo puede genera una carga cada 2 seg. \n Sifón de Maná: Los ataque restauran un  3% de tu Maná faltante al impacto.","attack_damage":40}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e047';
update public.wr_items b set ("price", "description", "attack_speed", "attack_damage") = (select r."price", r."description", r."attack_speed", r."attack_damage" from jsonb_populate_record(b, $rd${"price":3300,"description":"Sombra: Los ataques infligen 35 de daño mágico adicional al impacto. \n Yuxtaposición: Alterna entre los efectos al impacto de Luz y Oscuridad al atacar. Los ataques de Luz otorgan de 5 a 8 de Armadura y de Resistencia Mágica durante 5 seg. al impacto. Los ataques de Oscuridad otorgan un 11% de Penetración de Armadura y un 11% de Penetración de Magia durante 5 seg. al impacto. Cada efecto al impacto se acumula hasta 3 veces. Mientras tengas este objeto, la Penetración de Armadura y la Penetración de Magia adicionales que te otorga tendrán un máximo de 40%.","attack_speed":30,"attack_damage":40}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e04b';
