update public.wr_items b set ("price", "description", "attack_damage", "percentage_movement") = (select r."price", r."description", r."attack_damage", r."percentage_movement" from jsonb_populate_record(b, $rd${"price":2900,"description":"Pies Ligeros: +5% de velocidad de movimiento. \n Vals Espectral: Al impactar a un enemigo con un ataque, obtienes un 25% de Velocidad de Ataque y un 7% de Velocidad de Movimiento durante 6 seg. Las bonificaciones no se acumulan. (10 seg de enfriamiento, que se reduce en 1 seg al impactar a un objetivo con un ataque).","attack_damage":20,"percentage_movement":5}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e057';
