update public.wr_items b set ("price", "description", "adaptable_ad", "adaptable_ap", "ability_power", "attack_damage", "percentage_movement") = (select r."price", r."description", r."adaptable_ad", r."adaptable_ap", r."ability_power", r."attack_damage", r."percentage_movement" from jsonb_populate_record(b, $rd${"price":3100,"description":"Descarga: +5% de Velocidad de Movimiento. \n Caos: Obtienes 25 de Daño de Ataque o 50 de Poder de Habilidad (adaptable). \n Ira: los ataques infligen 30 de Daño Mágico adicional, pero ya no puedes causar golpes críticos. Por cada 1% de Tasa de Críticos que obtengas de los objetos, tu daño mágico aumente 1.5, hasta un máximo de 75 (se alcanza a un 50% de la Tasa de Críticos). \n  Ataque Furioso: Los ataques otorgan un 8% de Velocidad de Ataque. Esta bonificación se puede acumular hasta 4 veces y otorgar un máximo de 32% de Veloidad de Ataque. Al reunir el máximo de acumulaciones, cada 3 ataque(s) aplicas efectos al impacto 1 vez/veces más","adaptable_ad":25,"adaptable_ap":50,"ability_power":0,"attack_damage":0,"percentage_movement":5}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e08f';
