update public.wr_items b set ("description", "percentage_movement") = (select r."description", r."percentage_movement" from jsonb_populate_record(b, $rd${"description":"Implacable: +5% de velocidad de movimiento.\n Impulso: Moverte genera Impulso, lo que otorga hasta 40 de Velocidad de Movimiento al llegar a 100 acumulaciones. Atacar elimina todas las acumulaciones de Impulso. Las acumulaciones decaen cuando se afecta la velocidad de movimiento.\n Golpe Aplastante: Los ataques infligen hasta 100 de daño mágico adicional segun el Impulso acumulado. Los ataques cuerpo a cuerpo que consumen el Impulso máximo también ralentizan un 75% durante 1 seg.","percentage_movement":5}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e0a5';
