update public.wr_items b set ("life", "description") = (select r."life", r."description" from jsonb_populate_record(b, $rd${"life":350,"description":"Asombro: Otorga Vida adicional igual al 8% de Maná Máximo y restaura el 15% de todo el maná gastado. \n Carga de Maná: Aumenta el Maná Máximo en 12 en cada ataque, cada vez que gastas maná o al recibir daño de campeones, monstruos épicos o torres. Tiene un límite de 700 de Maná adicional y transforma Llegada del Invierno en Invierno Nórdico. Se activa hasta 3 veces cada 10 seg. Solo puedes llevar un objeto de Lágrima de la Diosa a la vez."}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e0b0';
