update public.wr_items b set ("description") = (select r."description" from jsonb_populate_record(b, $rd${"description":"Versátil: Obtienes 14 de Daño de Ataque o 28 de Poder de Habilidad (adaptable). \n Invocación Álmica: Cada 60 seg obtienes 75 de oro, 25 de Vida y 2 de Daño de Ataque o 4 de Poder de Habilidad (adaptable); hasta un máximo de 250 de Vida y 20 de Daño de Ataque o 40 de Poder de Habilidad (adaptable). Infliges 2 de daño adicional a los centinelas de visión que hayan sido revelados con Lente Revelados, Centinela de Control y Brote del Vidente. \n Obtienes un 10% de VElocidad de Movimiento al desplazarte hacia tu compañero perfecto fuera del combate. Si están a mas de 2500 unidades de distancia, esta bonificación aumenta a un 30%."}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e076';
