update public.wr_items b set ("description", "percentage_movement") = (select r."description", r."percentage_movement" from jsonb_populate_record(b, $rd${"description":"Vuelo: +5% de velocidad de movimiento.","percentage_movement":5}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e0b5';
update public.wr_items b set ("life", "mana", "price", "description", "ability_haste", "ability_power", "healing_and_shield") = (select r."life", r."mana", r."price", r."description", r."ability_haste", r."ability_power", r."healing_and_shield" from jsonb_populate_record(b, $rd${"life":100,"mana":300,"price":2800,"description":"Eco Armónico: Moverte y lanzar habilidades acumula Armonía. Al reunir 100 acumulaciones de Armonía, la siguiente habilidad que lances para curar u otorgar un escudo a un aliado le restaura (de 100 a 160 + 15 de poder de habilidad) de Vida adicional. Si el objetivo tiene menos de un 30% de Vida, la potencia de la curación aumenta a un 130% del valor original.","ability_haste":15,"ability_power":50,"healing_and_shield":5}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e0b7';
update public.wr_items b set ("magic_res", "description") = (select r."magic_res", r."description" from jsonb_populate_record(b, $rd${"magic_res":75,"description":"Aniquilamagos: Si no recibes daño mágico durante 12 seg, obtienes un escudo mágico que absorbe daño equivalente de 70 a 180 + 10% de vida máxima."}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e0b9';
update public.wr_items b set ("life", "armor", "price", "magic_res", "description") = (select r."life", r."armor", r."price", r."magic_res", r."description" from jsonb_populate_record(b, $rd${"life":0,"armor":60,"price":3100,"magic_res":60,"description":"Resistencia: Otorga 1 acumulación de resistencia cada 1 seg mientras estés en combate con campeones enemigos (máximo 5 acumulaciones). Con las acumulaciones máximas, obtienes un 20% de tamaño, un 20% de tenacidad, un 30% de armadura y un 30% de resistencia mágica hasta que estés fuera de combate contra campeones."}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e0bc';
update public.wr_items b set ("life", "armor", "price", "magic_res", "description") = (select r."life", r."armor", r."price", r."magic_res", r."description" from jsonb_populate_record(b, $rd${"life":350,"armor":40,"price":2600,"magic_res":0,"description":"Atrapador: Tras usar habilidades que aplican efectos de control de masas para desplazar al enemigo, obtienes un 10% de Velocidad de Movimiento durante 3 seg. Además, marcas al objetivo, lo que reduce su Armadura y su Resistencia Mágica entre 5 y 12 durante 8 seg. Si el objetivo muere mientras está marcado, su muerte otorga de 100 a 140 de oro adicional que se repartirá equitativamente entre tú y tus aliados cercanos. Este oro adicional solo se puede obtener una vez cada 10 seg."}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e0bd';
update public.wr_items b set ("life", "mana", "armor", "price", "magic_res", "description", "ability_haste") = (select r."life", r."mana", r."armor", r."price", r."magic_res", r."description", r."ability_haste" from jsonb_populate_record(b, $rd${"life":350,"mana":150,"armor":40,"price":2700,"magic_res":0,"description":"Mensajero: Al lanzar tu definitiva, te envuelve una tormenta de nieve durante 10 seg. La tormenta inflige un máximo de 320-600 de daño, ralentiza a los enemigos cercanos en un 25% y deja un rastro tras de ti. Los campeones aliados sobre la estela obtienen 40 de velocidad de movimiento adicional durante 1 seg. (30 seg de enfriamiento).","ability_haste":15}$rd$::jsonb) r) where b.id::text = '6a04bc1334f787bb5bb2e0bf';
